import { useEffect, useMemo, useState } from "react";
import PropTypes from "prop-types";

const STATUS_LABELS = { queued: "Queued", running: "Running…", done: "Done ✅", failed: "Failed" };
const MAX_ROWS = 250;

/** One run row with its elapsed time. */
function RunRow({ run, onOpen }) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (run.status !== "running") return undefined;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [run.status]);
  const elapsed = Math.max(0, Math.round((now - run.startedAt) / 1000));
  return (
    <li className={`run-row run-row--${run.status}`} data-id={run.id}>
      <button type="button" onClick={() => onOpen(run.id)} aria-label={`Open ${run.title}`}>
        <span className="run-row__title">{run.title}</span>
        <span className="run-row__status">{STATUS_LABELS[run.status] ?? run.status}</span>
        {run.status === "running" && <time dateTime={`PT${elapsed}S`}>{elapsed}s</time>}
      </button>
    </li>
  );
}

RunRow.propTypes = {
  run: PropTypes.shape({ id: PropTypes.string, title: PropTypes.string }).isRequired,
  onOpen: PropTypes.func.isRequired,
};

// The list keeps the newest runs first and caps how many it draws.
export default function RunList({ runs, filter = "", onOpen }) {
  const visible = useMemo(() => {
    const needle = filter.trim().toLowerCase();
    return runs
      .filter((run) => needle === "" || run.title.toLowerCase().includes(needle))
      .sort((a, b) => b.startedAt - a.startedAt)
      .slice(0, MAX_ROWS);
  }, [runs, filter]);
  if (visible.length === 0) {
    return <p className="run-list__empty">Nothing matches “{filter}” — try another word.</p>;
  }
  return (
    <ul className="run-list">
      {visible.map((run) => (
        <RunRow key={run.id} run={run} onOpen={onOpen} />
      ))}
    </ul>
  );
}

