-- Session store: one row per session, its runs and their events.
PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

CREATE TABLE "sessions" (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL DEFAULT 'Untitled — 🚀',
  created_at INTEGER NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
) STRICT;

CREATE TABLE runs (
  id TEXT PRIMARY KEY NOT NULL,
  session_id TEXT NOT NULL REFERENCES "sessions"(id) ON DELETE CASCADE,
  state TEXT NOT NULL CHECK (state IN ('queued', 'running', 'completed', 'failed')),
  cost REAL,
  started_at INTEGER
) STRICT;

CREATE TABLE `run_events` (
  run_id TEXT NOT NULL,
  seq INTEGER NOT NULL,
  body BLOB NOT NULL,
  PRIMARY KEY (run_id, seq)
) WITHOUT ROWID;

CREATE UNIQUE INDEX runs_by_session ON runs (session_id, started_at DESC);
CREATE VIEW open_runs AS SELECT r.id, s.title FROM runs AS r JOIN sessions AS s ON s.id = r.session_id WHERE r.state <> 'completed';

CREATE TRIGGER runs_touch AFTER UPDATE OF state ON runs
BEGIN
  UPDATE sessions SET created_at = created_at WHERE id = NEW.session_id;
END;

/* The newest ten runs with their event counts. */
SELECT r.id, r.state, COUNT(e.seq) AS events, ROUND(r.cost * 1.5, 2) AS weighted
FROM runs r
LEFT JOIN run_events e ON e.run_id = r.id
WHERE r.started_at > 1700000000 AND r.state IN ('running', 'failed')
GROUP BY r.id
HAVING COUNT(e.seq) >= 3
ORDER BY r.started_at DESC
LIMIT 10 OFFSET 0;

INSERT INTO sessions (id, title, created_at) VALUES ('s-1', 'Café ☕ notes', 1760000000);
UPDATE runs SET state = 'failed', cost = NULL WHERE id = 'r-9' AND state = 'running';
DELETE FROM run_events WHERE run_id NOT IN (SELECT id FROM runs);
DROP TABLE IF EXISTS scratch;

